import React,{useState,useEffect}from'react';
import{Link}from'react-router-dom';

export default function Header(){
const[isMobile,setIsMobile]=useState(false);
useEffect(()=>{
const handleResize=()=>setIsMobile(window.innerWidth<=768);
handleResize();
window.addEventListener('resize',handleResize);
return()=>window.removeEventListener('resize',handleResize);
},[]);
return(
<>
<style>{`
@keyframes rgbGlow{0%{filter:hue-rotate(0deg)}100%{filter:hue-rotate(360deg)}}
.rgb-animated-logo{animation:rgbGlow 6s linear infinite}
.nav-link:hover{color:#00D2C4!important;transform:translateY(-2px)}
.cta-button:hover{background-color:#00b3a6!important;box-shadow:0 0 18px rgba(0,210,196,.5);transform:translateY(-2px) scale(1.03)}
.logo-brand:hover{color:#00D2C4!important}
`}</style>
<nav style={{backgroundColor:'#070F1E',borderBottom:'1px solid rgba(255,255,255,.08)',padding:isMobile?'14px 18px':'18px 42px',display:'flex',justifyContent:'space-between',alignItems:'center',position:'sticky',top:0,zIndex:50,width:'100%',boxSizing:'border-box',minHeight:isMobile?'68px':'82px'}}>
<Link to="/" style={{display:'flex',alignItems:'center',gap:isMobile?'10px':'15px',textDecoration:'none',flexShrink:0}}>
<div className="rgb-animated-logo" style={{width:isMobile?'48px':'58px',height:isMobile?'48px':'58px',borderRadius:'13px',background:'linear-gradient(135deg,#00D2C4,#ff007f,#7928ca,#0070f3)',backgroundSize:'300% 300%',display:'flex',alignItems:'center',justifyContent:'center',color:'#fff',fontWeight:'bold',padding:'2px',boxShadow:'0 5px 18px rgba(0,210,196,.32)'}}>
<div style={{width:'100%',height:'100%',backgroundColor:'#070F1E',borderRadius:'11px',display:'flex',alignItems:'center',justifyContent:'center',overflow:'hidden',position:'relative'}}>
<img src="/assets/logo.png" alt="Vighnavi Academy Logo" onError={e=>{e.target.style.display='none'}} style={{width:'100%',height:'100%',objectFit:'cover'}}/>
<span style={{position:'absolute',fontSize:isMobile?'15px':'18px',fontWeight:'800',color:'#00D2C4'}}>VA</span>
</div>
</div>
<span className="logo-brand" style={{color:'#fff',fontSize:isMobile?'19px':'24px',fontWeight:'800',letterSpacing:'.6px',lineHeight:1.1,transition:'all .25s ease'}}>Vighnavi Academy</span>
</Link>
{!isMobile&&(
<div style={{display:'flex',alignItems:'center',gap:'38px',fontSize:'17px',fontWeight:'600'}}>
<Link to="/" className="nav-link" style={{color:'#d1d5db',textDecoration:'none',transition:'all .2s ease'}}>Home</Link>
<Link to="/about" className="nav-link" style={{color:'#d1d5db',textDecoration:'none',transition:'all .2s ease'}}>About Us</Link>
<Link to="/courses" className="nav-link" style={{color:'#d1d5db',textDecoration:'none',transition:'all .2s ease'}}>Courses</Link>
<Link to="/contact" className="nav-link" style={{color:'#d1d5db',textDecoration:'none',transition:'all .2s ease'}}>Testimonials</Link>
</div>
)}
<div>
<Link to="/contact" className="cta-button" style={{backgroundColor:'#00D2C4',color:'#000',padding:isMobile?'11px 17px':'13px 25px',borderRadius:'28px',textDecoration:'none',fontWeight:'700',fontSize:isMobile?'13px':'16px',display:'inline-block',transition:'all .3s ease',whiteSpace:'nowrap',boxShadow:'0 4px 12px rgba(0,210,196,.18)'}}>Book Consultation&nbsp; →</Link>
</div>
</nav>
</>
);
}
